import { Component, input } from '@angular/core';
import { FigurePipe } from '../../core/locale';

/** A period's line in the classic summary: its due-total counting each claim by its status now. */
export interface ClassicPeriodSummary {
  name: string;
  dueTotal: string;
}

// The sheet's classic summary, shown beside the summary: per period, the due-total counting each claim by
// its status now (a closed period keeps the figure fixed when it closed), and everyone's due-total added up
// with no trimming.
@Component({
  selector: 'app-classic-summary',
  imports: [FigurePipe],
  template: `
    <section aria-labelledby="classic-summary-heading">
      <h2 id="classic-summary-heading">Classic summary</h2>
      <table>
        <caption>By period</caption>
        <thead>
          <tr>
            <th scope="col">Period</th>
            <th scope="col">Due</th>
          </tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'classic-period-' + p.name + '-due-total'">{{ p.dueTotal | figure }}</td>
            </tr>
          }
        </tbody>
      </table>
      <p>Due-total: <span data-testid="classic-due-total">{{ dueTotal() | figure }}</span></p>
    </section>
  `,
})
export class ClassicSummary {
  readonly periods = input.required<ClassicPeriodSummary[]>();
  readonly dueTotal = input.required<string>();
}
import { Component, input } from '@angular/core';
import { FigurePipe } from '../../core/locale';

/**
 * A grade's line: how many people are on it today (retired people left out), how many of those are
 * active, and their due-totals added up.
 */
export interface GradeSummary {
  grade: string;
  count: number;
  active: number;
  dueTotal: string;
}

/**
 * A period's line: its due-total, as its row in the periods list shows it, and its change from the
 * period before it by start date (empty for the earliest).
 */
export interface PeriodSummary {
  name: string;
  dueTotal: string;
  change: string;
}

/** A status's line: how many of the sheet's claims have it. */
export interface StatusSummary {
  status: string;
  count: number;
}

/** A void reason's line: how many of the sheet's VOID claims were voided with it. */
export interface VoidReasonSummary {
  reason: string;
  count: number;
}

// The sheet's summary: per grade, per period, per claim status and per void reason, with the claims late in review, each figure worked from what the
// lists show.
@Component({
  selector: 'app-summary',
  imports: [FigurePipe],
  template: `
    <section aria-labelledby="summary-heading">
      <h2 id="summary-heading">Summary</h2>
      <table>
        <caption>By grade</caption>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">People</th>
            <th scope="col">Due</th>
            <th scope="col">Active</th>
          </tr>
        </thead>
        <tbody>
          @for (g of grades(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal | figure }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-active'">{{ g.active }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By period</caption>
        <thead>
          <tr>
            <th scope="col">Period</th>
            <th scope="col">Due</th>
            <th scope="col">Change</th>
          </tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ p.dueTotal | figure }}</td>
              <td [attr.data-testid]="'summary-period-' + p.name + '-change'">{{ p.change | figure }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By status</caption>
        <thead>
          <tr>
            <th scope="col">Status</th>
            <th scope="col">Claims</th>
          </tr>
        </thead>
        <tbody>
          @for (s of statuses(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
      <p>Late in review: <span data-testid="summary-review-late-count">{{ reviewLateCount() }}</span></p>
      <table>
        <caption>By void reason</caption>
        <thead>
          <tr>
            <th scope="col">Reason</th>
            <th scope="col">Voided claims</th>
          </tr>
        </thead>
        <tbody>
          @for (v of voidReasons(); track v.reason) {
            <tr>
              <th scope="row">{{ v.reason }}</th>
              <td [attr.data-testid]="'summary-void-' + v.reason + '-count'">{{ v.count }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Summary {
  readonly grades = input.required<GradeSummary[]>();
  readonly periods = input.required<PeriodSummary[]>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly voidReasons = input.required<VoidReasonSummary[]>();
  /** How many REVIEW claims are late in review. */
  readonly reviewLateCount = input.required<number>();
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: what each person has claimed, their due-total and
 * overdue-total, and the sheet's claimed-total, due-total and overdue-total. A change takes them
 * before it writes and has them audited after its own records, so every figure it moves is recorded.
 */
@Service
public class Rollups {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /**
     * A person's figures: what they have claimed, their due-total (null when n/a) and their
     * overdue-total (the due of their counting overdue claims).
     */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {

        boolean sameAs(Figures other) {
            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal)
                    && same(overdueTotal, other.overdueTotal);
        }
    }

    /**
     * The sheet's figures: each person's by id, in list order, the sheet's totals, and how many of its
     * counting claims are overdue.
     */
    public record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal, int overdueCount) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final SheetRepository sheets;
    private final Dues dues;
    private final Audit audit;

    public Rollups(PersonRepository people, ClaimRepository claims, SheetRepository sheets,
            Dues dues, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.dues = dues;
        this.audit = audit;
    }

    /** The sheet's figures as they stand now in the current transaction. */
    public Rollup take(String sheetId) {
        Map<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        return take(sheets.findById(sheetId).orElse(null), dues.live(sheetId), sheetPeople,
                claims.findBySheetIdOrderByIdDesc(sheetId));
    }

    /**
     * A sheet's figures read from what is given, held in no store or not: the sheet (null when not found;
     * its today is the day they are read on), the basis their dues are read against, its people by id in
     * list order, and its claims.
     */
    public Rollup take(Sheet sheet, Dues.Basis basis, Map<Long, Person> sheetPeople, Iterable<Claim> sheetClaims) {
        LocalDate today = sheet == null ? null : sheet.getToday();
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        for (Claim claim : sheetClaims) {
            if (claim.getStatus().counts()) {
                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        int overdueCount = 0;
        for (Map.Entry<Long, Person> entry : sheetPeople.entrySet()) {
            Person person = entry.getValue();
            List<Claim> personClaims = byPerson.getOrDefault(entry.getKey(), List.of());
            BigDecimal claimed = zero();
            for (Claim claim : personClaims) {
                // What is claimed leaves out claims that correct another.
                if (person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today)
                        && (claim.getCorrects() == null || claim.getCorrects().isBlank())) {
                    claimed = claimed.add(claim.getAmount());
                }
            }
            List<Claim> counting = personClaims.stream()
                    .filter(claim -> person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today))
                    .toList();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean figured = false;
            for (Claim claim : counting) {
                String grade = person.gradeOn(claim.getDate());
                boolean late = overdue(claim, sheet, grade);
                if (late) {
                    overdueCount++;
                }
                BigDecimal figure = dues.due(claim, grade, basis);
                if (figure != null) {
                    due = due.add(figure);
                    figured = true;
                    if (late) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
            // figure (a fixed one, or one at the grade in force on its own date).
            boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
